const rowNumberOf = (row, index) => Number(row.row_number ?? row.rowNumber ?? index + 2);
// Ưu tiên item pairing; nếu node RSS không truyền pairedItem thì suy ra nguồn rss.
let src;
try {
  src = $('Lọc nguồn đang bật').item.json;
